insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'Geste d''ancrage avant le café du matin', 'Tous les jours · 2 min', 'Exercice'::public.module_kind, 1, now(), '{"duree":"2 minutes","quand":"Le matin, avant la première gorgée de café","steps":["Debout, les deux pieds bien à plat, posez la main droite au centre du sternum.","Trois respirations lentes, en laissant l''expiration durer plus longtemps que l''inspiration.","Retirez la main et buvez la première gorgée en gardant la sensation de chaleur sous la main."],"why":"Le geste doit exister avant d''être utile. On l''installe sur un moment calme et quotidien pour qu''il soit disponible le jour où la porte claque.","quiz":[{"question":"À quel moment de la journée ce geste est-il prévu ?","options":["Quand l''envie de fumer arrive","Le matin, avant la première gorgée de café","Le soir avant de dormir"],"correct":1,"feedback":"On l''installe sur un moment calme et répété. C''est ce qui le rend disponible plus tard, quand la journée dérape."},{"question":"L''expiration doit être…","options":["Plus courte que l''inspiration","De la même durée","Plus longue que l''inspiration"],"correct":2,"feedback":"C''est l''expiration longue qui fait le travail. L''inspiration, elle, se fait toute seule."}]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000001' and position = 1);
insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'Noter la situation la plus difficile de la journée', 'Mardi soir', 'Journal'::public.module_kind, 2, now(), '{"duree":"3 minutes","quand":"Le soir, avant de vous coucher","steps":["Écrivez ce qui s''est passé, en une ou deux phrases, sans chercher à expliquer.","Notez ce que le corps a fait à ce moment-là, avant les pensées.","Notez ce que vous avez fait juste après."],"why":"Ce n''est pas un journal intime. C''est la matière première de la prochaine séance : ce que vous notez à chaud, vous ne vous le rappellerez pas jeudi."}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000001' and position = 2);
