insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'Lettre à la cigarette', 'Avant la prochaine séance', 'Écriture'::public.module_kind, 5, null, '{"duree":"20 minutes, en une seule fois","quand":"Quand vous avez du temps devant vous, pas le soir","steps":["Écrivez-lui comme à quelqu''un qui a compté. Ce qu''elle vous a apporté, ce qu''elle vous a coûté.","Dites-lui ce que vous avez trouvé ailleurs, ou ce que vous cherchez encore.","Ne la relisez pas. Apportez-la jeudi, pliée, vous décidez sur place si vous la lisez à voix haute."]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000001' and position = 5);
