insert into public.psych_profiles (cabinet_id, patient_id, version, sessions_count, portrait, axes, levers, care) values ('20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 1, 3, 'Fonctionne au contrat clair : ce qui est nommé et daté est fait. L''envie de fumer s''est déplacée du manque physique vers un réflexe de soulagement après les tensions relationnelles. Bonne réceptivité aux inductions courtes ; l''attention décroche autour de la dixième minute sur les imageries longues.', '[{"label":"Besoin de contrôle","value":78,"note":"Se détend dès que le déroulé est annoncé"},{"label":"Réceptivité hypnotique","value":62,"note":"Voie kinesthésique, peu visuelle"},{"label":"Tolérance à l''émotion forte","value":45,"note":"Coupe court quand ça monte"},{"label":"Autonomie entre séances","value":84,"note":"Fait les exercices sans relance"},{"label":"Appui sur le corps","value":58,"note":"L''ancrage marche mieux que le récit"}]'::jsonb, '[{"title":"Annoncer le déroulé avant l''induction","body":"Deux phrases sur les étapes et la durée suffisent à faire baisser la vigilance."},{"title":"Rester sous quinze minutes","body":"Au-delà, elle décroche et repart avec le sentiment d''avoir mal fait."},{"title":"Travailler le déclencheur relationnel","body":"L''envie revient après un appel ou un conflit, pas après les repas. Cibler là."},{"title":"Faire nommer la réussite à voix haute","body":"Elle minimise ses avancées. Les vingt minutes tenues valent d''être redites."}]'::jsonb, '["Éviter la régression en enfance avant la séance 5 : la tolérance émotionnelle reste moyenne.","Ne pas commenter les rechutes en chiffres, elle les vit comme une rupture de contrat."]'::jsonb) on conflict (patient_id, version) do nothing;
insert into public.journal_pages (cabinet_id, patient_id, title, body, shared, written_at) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'La soirée de vendredi', 'Deux personnes fumaient sur le trottoir. Je suis restée dedans, j''ai fait le geste de la main sur le sternum, et l''envie est passée en trois ou quatre minutes. Je ne pensais pas que ce serait aussi bête que ça.', true, now() where not exists (select 1 from public.journal_pages where patient_id = '30000000-0000-4000-8000-000000000001' and title = 'La soirée de vendredi');
insert into public.journal_pages (cabinet_id, patient_id, title, body, shared, written_at) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'Ce que je ne dis pas au bureau', 'J''ai recommencé à compter les heures avant la pause. Personne ne le voit. Je ne sais pas encore si j''ai envie d''en parler en séance.', false, now() where not exists (select 1 from public.journal_pages where patient_id = '30000000-0000-4000-8000-000000000001' and title = 'Ce que je ne dis pas au bureau');
