insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000002', 'Anamnèse et objectifs de la thérapie', 'À remplir avant la séance 2', 'Formulaire'::public.module_kind, 0, now(), '{"duree":"15 minutes","quand":"Avant la deuxième séance","steps":["Répondez au questionnaire à votre rythme, il s''enregistre tout seul.","Sur la dernière question, indiquez ce qui aurait changé dans six mois pour que vous soyez satisfaite.","Laissez en blanc ce que vous préférez dire de vive voix."]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000002' and position = 0);
insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000002', 'Cohérence cardiaque, matin et soir', 'Tous les jours · 5 min', 'Exercice'::public.module_kind, 1, now(), '{"duree":"5 minutes, deux fois","quand":"Au réveil et avant de monter vous coucher","steps":["Assise, dos appuyé, téléphone hors de portée.","Inspirez 5 secondes, expirez 5 secondes. Six respirations par minute pendant cinq minutes.","Le soir, faites-le avant d''entrer dans la chambre, pas dans le lit."],"why":"L''exercice du soir compte plus que celui du matin. C''est celui qui coupe l''alerte avant que la liste ne commence.","quiz":[{"question":"Quel est le rythme respiratoire de l''exercice ?","options":["5 secondes d''inspiration, 5 secondes d''expiration","3 secondes, 7 secondes","Le plus lent possible"],"correct":0,"feedback":"Six respirations par minute, ni plus lentes ni plus profondes. C''est la régularité qui compte."},{"question":"Où faire l''exercice du soir ?","options":["Dans le lit, juste avant de dormir","Avant d''entrer dans la chambre","Peu importe"],"correct":1,"feedback":"Avant d''entrer dans la chambre. On sépare le retour au calme du moment de l''endormissement, sinon la chambre devient le lieu de l''effort."}]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000002' and position = 1);
