insert into public.psych_profiles (cabinet_id, patient_id, version, sessions_count, portrait, axes, levers, care) values ('20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000002', 1, 1, 'Une seule séance : tout est encore à confirmer. L''anticipation domine, le corps se tend avant l''événement plutôt que pendant. Exécution des consignes irréprochable, au point que l''assiduité peut devenir une performance de plus à réussir.', '[{"label":"Anticipation anxieuse","value":82,"note":"Le stress précède la situation"},{"label":"Besoin de bien faire","value":88,"note":"100 % des modules dès la semaine 1"},{"label":"Réceptivité hypnotique","value":50,"note":"Une seule induction, non évaluée"},{"label":"Accès aux émotions","value":40,"note":"Décrit des sensations, pas des affects"},{"label":"Appui sur le corps","value":66,"note":"La cohérence cardiaque prend bien"}]'::jsonb, '[{"title":"Dédramatiser l''assiduité","body":"Dire explicitement qu''un module sauté n''est pas un échec, sinon le programme devient une source de stress de plus."},{"title":"Passer par la sensation","body":"Elle nomme le serrement avant l''émotion. Partir du corps donne accès au reste."},{"title":"Tester deux inductions différentes","body":"Rien ne permet encore de savoir ce qui fonctionne le mieux. La séance 2 sert à ça."}]'::jsonb, '["Profil établi sur une séance : à traiter comme une hypothèse de travail.","Surveiller le transfert de performance sur la thérapie elle-même."]'::jsonb) on conflict (patient_id, version) do nothing;
insert into public.journal_pages (cabinet_id, patient_id, title, body, shared, written_at) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000002', 'La liste de quatre heures', 'Toujours le même ordre : les mails, la réunion de jeudi, ma mère. Je note maintenant les trois items dès qu''ils arrivent, ça les rend plus petits sur le papier.', true, now() where not exists (select 1 from public.journal_pages where patient_id = '30000000-0000-4000-8000-000000000002' and title = 'La liste de quatre heures');
