insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000003', 'Reformuler une phrase par jour', 'Tous les jours', 'Exercice'::public.module_kind, 1, null, '{"duree":"Le temps d''une phrase","quand":"Dans une conversation réelle, chaque jour","steps":["Choisissez un moment où l''autre dit quelque chose qui vous pique.","Avant de répondre, reformulez ce qu''il vient de dire : « si je comprends bien, tu… ».","Notez ici sa réaction, en trois mots."],"why":"On ne travaille pas votre façon de parler mais le temps que vous prenez avant de parler.","quiz":[{"question":"Que faites-vous avant de répondre ?","options":["Vous préparez votre argument","Vous reformulez ce que l''autre vient de dire","Vous respirez trois fois"],"correct":1,"feedback":"Reformuler d''abord. Cela vous donne le temps que vous cherchez, sans avoir à le demander."},{"question":"Que notez-vous après l''échange ?","options":["Sa réaction, en trois mots","Ce que vous auriez dû dire","Rien, l''exercice est fini"],"correct":0,"feedback":"Trois mots sur sa réaction. C''est la matière qu''on regardera ensemble."}]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000003' and position = 1);
insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000003', 'Noter un échange réussi', 'Mercredi', 'Journal'::public.module_kind, 2, null, '{"duree":"2 minutes","quand":"Mercredi soir","steps":["Un seul échange, même minuscule, même avec un commerçant.","Notez ce que vous avez fait, pas ce que l''autre a fait.","Relisez-le avant la prochaine séance."]}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000003' and position = 2);
