insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000003', 'Reprendre rendez-vous', 'Relance envoyée vendredi', 'Séance'::public.module_kind, 4, null, '{"duree":"1 minute","quand":"Dès que vous voyez ce module","steps":["Ouvrez l''agenda et prenez le premier créneau qui vous convient.","Si aucun créneau ne convient, écrivez-le ici, Laetitia vous rappelle."],"why":"Un programme interrompu à la cinquième semaine sur six perd l''essentiel de ce qui a été construit. Reprendre maintenant coûte moins que recommencer."}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000003' and position = 4);
