insert into public.psych_profiles (cabinet_id, patient_id, version, sessions_count, portrait, axes, levers, care) values ('20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000003', 1, 4, 'Évitement du conflit ancien et bien installé, appris tôt en famille. Les séances sont vécues comme utiles, l''entre-séances comme une charge supplémentaire. Le décrochage actuel ne signale pas un désaccord thérapeutique mais une difficulté à s''accorder du temps sans justification extérieure.', '[{"label":"Évitement du conflit","value":86,"note":"Se retire avant le désaccord"},{"label":"Engagement entre séances","value":32,"note":"41 % des modules, en baisse"},{"label":"Réceptivité hypnotique","value":71,"note":"Entre vite, ressort apaisé"},{"label":"Capacité d''auto-observation","value":64,"note":"Nouvelle : il repère sur le moment"},{"label":"Demande d''aide explicite","value":25,"note":"Ne relance jamais de lui-même"}]'::jsonb, '[{"title":"Un seul exercice, daté","body":"Cinq modules ouverts le figent. Un exercice avec un jour précis passe mieux qu''une consigne quotidienne."},{"title":"Reprendre le repas de famille","body":"Il a remarqué son silence sur le moment : premier signe de recul, à nommer comme un acquis."},{"title":"Proposer la date, ne pas l''attendre","body":"Il ne redemandera pas de rendez-vous. Poser la date en fin de séance."},{"title":"Autoriser le désaccord en séance","body":"L''espace thérapeutique est le seul endroit où il peut s''entraîner à ne pas être d''accord."}]'::jsonb, '["Le silence entre les séances n''est pas un refus : ne pas lire le décrochage comme une fin de suivi.","Éviter les relances multiples, elles réactivent la peur de décevoir."]'::jsonb) on conflict (patient_id, version) do nothing;
