insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000004', 'Prendre la parole une fois par jour', 'Tous les jours', 'Exercice'::public.module_kind, 1, now(), '{"duree":"Quelques secondes","quand":"Chaque jour, dans un cadre au choix","steps":["Une intervention par jour, aussi courte que vous voulez, même une question.","Avant de parler, sentez vos pieds sur le sol et attendez une respiration complète.","Notez ici si la voix a tremblé, oui ou non. Rien de plus."],"why":"Ce qui compte n''est pas la qualité de l''intervention mais la répétition. On use le mur, on ne le franchit pas d''un coup."}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000004' and position = 1);
