insert into public.patient_modules (cabinet_id, patient_id, title, meta, kind, position, done_at, consigne) select '20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000004', 'Préparer la présentation du 15', 'Avant vendredi', 'Écriture'::public.module_kind, 3, null, '{"duree":"30 minutes","quand":"Avant vendredi","steps":["Écrivez seulement les trois idées que vous voulez qu''on retienne. Pas les diapositives.","Pour chacune, une phrase que vous diriez à un ami au téléphone.","Lisez ces trois phrases à voix haute, debout, une fois."],"why":"Nous préparons le sol, pas le texte."}'::jsonb where not exists (select 1 from public.patient_modules where patient_id = '30000000-0000-4000-8000-000000000004' and position = 3);
