insert into public.psych_profiles (cabinet_id, patient_id, version, sessions_count, portrait, axes, levers, care) values ('20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000004', 1, 2, 'Progression rapide, portée par une exigence de soi qui est à la fois le moteur et le risque. La confiance monte tant que les tentatives réussissent ; un seul épisode raté peut faire retomber la courbe d''un coup. Imagerie mentale très nette : la visualisation donne plus que l''analyse.', '[{"label":"Exigence envers soi","value":84,"note":"Juge sévèrement ses tentatives"},{"label":"Réceptivité hypnotique","value":79,"note":"Imagerie visuelle rapide"},{"label":"Confiance situationnelle","value":55,"note":"Variable selon l''audience"},{"label":"Autonomie entre séances","value":70,"note":"Constante, sans relance"},{"label":"Tolérance à l''échec","value":38,"note":"Point de fragilité principal"}]'::jsonb, '[{"title":"Préparer l''échec pendant que ça monte","body":"Installer maintenant une réponse à la prise de parole ratée, tant que la courbe est favorable."},{"title":"Continuer par la visualisation","body":"La scène réussie produit plus de résultats que l''exploration de ce qui bloque."},{"title":"Élargir l''audience par paliers","body":"Onze personnes ont été tenues. La marche suivante se pose, elle ne se saute pas."}]'::jsonb, '["Éviter de poser la présentation du 15 comme un test : elle en ferait un verdict.","Profil établi sur deux séances : la tolérance à l''échec reste à vérifier en situation."]'::jsonb) on conflict (patient_id, version) do nothing;
