insert into public.psych_profiles (cabinet_id, patient_id, version, sessions_count, portrait, axes, levers, care) values ('20000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000005', 1, 8, 'Programme terminé, acquis stables depuis trois semaines. Il a intégré ses outils et les utilise sans consigne. Le risque n''est plus le stress lui-même mais l''arrêt complet du suivi : il considère volontiers qu''un problème résolu ne revient pas.', '[{"label":"Autonomie","value":92,"note":"Écoute libre, sans rappel"},{"label":"Réceptivité hypnotique","value":80,"note":"Auto-hypnose acquise"},{"label":"Stabilité émotionnelle","value":78,"note":"Trois semaines sans épisode"},{"label":"Lecture des signaux faibles","value":60,"note":"Repère tard la montée"},{"label":"Recours spontané à l''aide","value":45,"note":"Attend que ce soit sévère"}]'::jsonb, '[{"title":"Espacer sans fermer","body":"Une séance de consolidation par trimestre maintient le lien sans réinstaller la dépendance."},{"title":"Travailler les signaux précoces","body":"Il agit quand le stress est déjà à 6. Lister avec lui les signes à 3."},{"title":"Garder l''audio court accessible","body":"C''est son outil de secours : vérifier qu''il est toujours sur le téléphone."}]'::jsonb, '["Ne pas clore le suivi sans point de reprise daté."]'::jsonb) on conflict (patient_id, version) do nothing;
